119	// DeleteCustomer removes a customer.
120	func (s *Store) DeleteCustomer(orgID, id string) error {
121		s.mu.Lock()
122		defer s.mu.Unlock()
123		c, ok := s.customers[id]
124		if !ok || c.OrgID != orgID {
125			return ErrNotFound
126		}
127		delete(s.customers, id)
128		if s.customersByEmail[emailKey{orgID, normEmail(c.Email)}] == id {
129			delete(s.customersByEmail, emailKey{orgID, normEmail(c.Email)})
130		}
131		return nil
132	}
