134	func copyCustomer(c Customer) Customer {
135		if c.Metadata != nil {
136			m := make(map[string]string, len(c.Metadata))
137			for k, v := range c.Metadata {
138				m[k] = v
139			}
140			c.Metadata = m
141		}
142		return c
143	}
