145	func sortCustomers(cs []Customer) {
146		sort.Slice(cs, func(i, j int) bool {
147			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
148				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
149			}
150			return cs[i].ID < cs[j].ID
151		})
152	}
